@MainActor
final class NexaImageBench: NSObject {
    static let shared = NexaImageBench()
    private var startTime = 0.0
    private var firstCPU = 0.0
    private var startResident: UInt64 = 0
    private var peakResident: UInt64 = 0
    private var thumbnails: Set<ObjectIdentifier> = []
    private var thumbnailSize = CGSize.zero
    private var loaded = 0
    private var previous = 0.0
    private var intervals: [Double] = []
    private var link: CADisplayLink?

    func start() {
        firstCPU = cpuSeconds()
        let memory = residentBytes()
        startResident = memory.current
        startTime = CACurrentMediaTime()
        previous = startTime
        let link = CADisplayLink(target: self, selector: #selector(frame))
        link.preferredFramesPerSecond = 60
        link.add(to: .main, forMode: .common)
        self.link = link
    }

    @objc private func frame() {
        let now = CACurrentMediaTime()
        intervals.append((now - previous) * 1000)
        previous = now
    }

    func didLoad(_ image: UIImage) {
        thumbnails.insert(ObjectIdentifier(image))
        thumbnailSize = image.size
        loaded += 1
        guard loaded == 24 else { return }
        extendLifetimeForRender()
    }

    private func extendLifetimeForRender() {
        let loadedTime = CACurrentMediaTime()
        let loadedCPU = cpuSeconds()
        let loadedMemory = residentBytes()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            let memory = self.residentBytes()
            let counters: [String: Any] = [
                "images": self.loaded,
                "distinctDecodedObjects": self.thumbnails.count,
                "width": self.thumbnailSize.width,
                "height": self.thumbnailSize.height,
                "wallSecondsToAllImages": loadedTime - self.startTime,
                "cpuSecondsToAllImages": loadedCPU - self.firstCPU,
                "residentStart": self.startResident,
                "residentAllImages": loadedMemory.current,
                "peakResident": memory.peak,
                "residentAfterRender": memory.current,
                "callbackIntervalsToAllImagesMs": self.intervals,
            ]
            if let bytes = try? JSONSerialization.data(withJSONObject: counters) {
                try? bytes.write(to: URL.documentsDirectory.appendingPathComponent("image-perf.json"), options: .atomic)
            }
            self.link?.invalidate()
            self.link = nil
        }
    }

    private func cpuSeconds() -> Double {
        var usage = rusage()
        getrusage(RUSAGE_SELF, &usage)
        return Double(usage.ru_utime.tv_sec + usage.ru_stime.tv_sec)
          + Double(usage.ru_utime.tv_usec + usage.ru_stime.tv_usec) / 1_000_000
    }

    private func residentBytes() -> (current: UInt64, peak: UInt64) {
        var info = mach_task_basic_info()
        var count = mach_msg_type_number_t(MemoryLayout<mach_task_basic_info>.size / MemoryLayout<integer_t>.size)
        let status = withUnsafeMutablePointer(to: &info) {
            $0.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                task_info(mach_task_self_, task_flavor_t(MACH_TASK_BASIC_INFO), $0, &count)
            }
        }
        return status == KERN_SUCCESS ? (info.resident_size, info.resident_size_max) : (0, 0)
    }
}
